describe('Table Row Numbers', () => {
    beforeEach(() => {
        cy.visit('/table-list'); // Adjust the URL to match your application
    });

    it('should display row numbers in the first column', () => {
        cy.get('table tbody tr').each((row, index) => {
            cy.wrap(row).find('td:first').should('have.text', (index + 1).toString());
        });
    });

    it('should not display row numbers if the table is empty', () => {
        cy.get('table tbody').should('be.empty');
        cy.get('table tbody tr').should('have.length', 0);
    });
});
